Action: run_sql({'query': "WITH insp_crit AS (\n    SELECT \n        i.inspection_id,\n        i.slchd_establishment_key,\n        ek.name,\n        i.inspection_date,\n        EXTRACT(year FROM i.inspection_date) as yr,\n        COUNT(CASE WHEN vc.critical THEN 1 END) as critical_count\n    FROM inspections i\n    JOIN establishment_keys ek ON i.slchd_establishment_key = ek.slchd_establishment_key\n    LEFT JOIN violations v ON i.inspection_id = v.inspection_id\n    LEFT JOIN violation_codes vc ON v.violation_code_id = vc.violation_code_id\n    WHERE i.inspection_date >= '2021-01-01'\n    GROUP BY i.inspection_id, i.slchd_establishment_key, ek.name, i.inspection_date\n),\nperiod_stats AS (\n    SELECT \n        slchd_establishment_key,\n        name,\n        AVG(CASE WHEN yr BETWEEN 2021 AND 2023 THEN critical_count END) as avg_early_crit,\n        AVG(CASE WHEN yr BETWEEN 2024 AND 2026 THEN critical_count END) as avg_late_crit,\n        COUNT(CASE WHEN yr BETWEEN 2021 AND 2023 THEN 1 END) as count_early,\n        COUNT(CASE WHEN yr BETWEEN 2024 AND 2026 THEN 1 END) as count_late\n    FROM insp_crit\n    GROUP BY slchd_establishment_key, name\n)\nSELECT \n    name,\n    slchd_establishment_key,\n    ROUND(avg_early_crit, 2) as avg_early,\n    ROUND(avg_late_crit, 2) as avg_late,\n    ROUND(avg_late_crit - avg_early_crit, 2) as change_in_crit\nFROM period_stats\nWHERE count_early >= 1 AND count_late >= 1\nORDER BY change_in_crit DESC\nLIMIT 15"})

