Action: run_sql({'query': "WITH insp_crit AS (\n    SELECT \n        i.inspection_id,\n        i.slchd_establishment_key,\n        ek.name,\n        i.inspection_date,\n        COUNT(CASE WHEN vc.critical THEN 1 END) as critical_count,\n        ROW_NUMBER() OVER (PARTITION BY i.slchd_establishment_key ORDER BY i.inspection_date ASC) as rn_first,\n        ROW_NUMBER() OVER (PARTITION BY i.slchd_establishment_key ORDER BY i.inspection_date DESC) as rn_last,\n        COUNT(*) OVER (PARTITION BY i.slchd_establishment_key) as total_insps\n    FROM inspections i\n    JOIN establishment_keys ek ON i.slchd_establishment_key = ek.slchd_establishment_key\n    LEFT JOIN violations v ON i.inspection_id = v.inspection_id\n    LEFT JOIN violation_codes vc ON v.violation_code_id = vc.violation_code_id\n    WHERE i.inspection_date >= '2021-01-01'\n    GROUP BY i.inspection_id, i.slchd_establishment_key, ek.name, i.inspection_date\n),\nfirst_last AS (\n    SELECT \n        f.slchd_establishment_key,\n        f.name,\n        f.critical_count as first_crit,\n        l.critical_count as last_crit,\n        (l.critical_count - f.critical_count) as diff\n    FROM insp_crit f\n    JOIN insp_crit l ON f.slchd_establishment_key = l.slchd_establishment_key\n    WHERE f.rn_first = 1 AND l.rn_last = 1 AND f.total_insps >= 2\n)\nSELECT \n    CASE \n        WHEN diff > 0 THEN 'Increased'\n        WHEN diff < 0 THEN 'Decreased'\n        ELSE 'Unchanged'\n    END as trend,\n    COUNT(*) as num_restaurants,\n    ROUND(AVG(diff), 2) as avg_diff\nFROM first_last\nGROUP BY trend"})

