Action: run_sql({'query': "WITH insp_crit AS (\n    SELECT \n        i.inspection_id,\n        i.slchd_establishment_key,\n        ek.name,\n        ek.address,\n        ek.city,\n        i.inspection_date,\n        EXTRACT(year FROM i.inspection_date) as yr,\n        COUNT(CASE WHEN vc.critical THEN 1 END) as critical_count\n    FROM inspections i\n    JOIN establishment_keys ek ON i.slchd_establishment_key = ek.slchd_establishment_key\n    LEFT JOIN violations v ON i.inspection_id = v.inspection_id\n    LEFT JOIN violation_codes vc ON v.violation_code_id = vc.violation_code_id\n    WHERE i.inspection_date >= '2021-01-01'\n    GROUP BY i.inspection_id, i.slchd_establishment_key, ek.name, ek.address, ek.city, i.inspection_date\n),\nperiod_stats AS (\n    SELECT \n        slchd_establishment_key,\n        CONCAT(name, ' (', city, ')') as restaurant,\n        AVG(CASE WHEN yr BETWEEN 2021 AND 2023 THEN critical_count END) as avg_early,\n        AVG(CASE WHEN yr BETWEEN 2024 AND 2026 THEN critical_count END) as avg_late,\n        COUNT(CASE WHEN yr BETWEEN 2021 AND 2023 THEN 1 END) as cnt_early,\n        COUNT(CASE WHEN yr BETWEEN 2024 AND 2026 THEN 1 END) as cnt_late\n    FROM insp_crit\n    GROUP BY slchd_establishment_key, name, city\n    HAVING cnt_early >= 1 AND cnt_late >= 1\n)\nSELECT \n    restaurant,\n    ROUND(avg_early, 2) as early_avg_critical,\n    ROUND(avg_late, 2) as late_avg_critical,\n    ROUND(avg_late - avg_early, 2) as critical_increase\nFROM period_stats\nWHERE avg_late > avg_early\nORDER BY critical_increase DESC\nLIMIT 10"})

