Action: run_sql({'query': "SELECT \n    CAST(EXTRACT(year FROM i.inspection_date) AS VARCHAR) as year,\n    ROUND(COUNT(CASE WHEN vc.critical THEN 1 END) * 1.0 / COUNT(DISTINCT i.inspection_id), 2) as avg_critical_per_inspection,\n    COUNT(DISTINCT i.inspection_id) as total_inspections\nFROM inspections i\nLEFT JOIN violations v ON i.inspection_id = v.inspection_id\nLEFT JOIN violation_codes vc ON v.violation_code_id = vc.violation_code_id\nWHERE i.inspection_date >= '2021-01-01'\nGROUP BY EXTRACT(year FROM i.inspection_date)\nORDER BY year ASC"})

